def simulate(g, dry_holes=False):
    R,C=len(g),len(g[0])
    out=[row[:] for row in g]
    seed_col=[c for c in range(C) if g[0][c]==2]
    cur=set(seed_col)
    for r in range(R):
        is8 = 8 in g[r]
        if is8:
            holes={c for c in range(C) if g[r][c]==0}
            wet = holes & cur if cur else set()
            if dry_holes: wet = holes
            for c in wet: out[r][c]=2
            cur=set(wet)
        else:
            if r>0:
                if r+1<R and 8 in g[r+1] and cur:
                    H={c for c in range(C) if g[r+1][c]==0}
                    new=set()
                    for e in cur:
                        c=e
                        while c>=0 and c not in H: c-=1
                        if c<0: c=0
                        new.update(range(c,e+1))
                        c=e
                        while c<C and c not in H: c+=1
                        if c>=C: c=C-1
                        new.update(range(e,c+1))
                    cur=new
                for c in cur: out[r][c]=2
    return out

