def simulate(g):
    import copy
    horiz = any(sum(1 for v in row if v==8)>len(g[0])//2 for row in g)
    def run(gg, out):
        R,C=len(gg),len(gg[0])
        cur={c for c in range(C) if gg[0][c]==2}
        for r in range(R):
            is8 = sum(1 for v in gg[r] if v==8)>C//2
            if is8:
                holes={c for c in range(C) if gg[r][c]==0}
                wet=holes & cur
                for c in wet: out[r][c]=2
                cur=set(wet)
            else:
                if r>0:
                    if r+1<R and sum(1 for v in gg[r+1] if v==8)>C//2 and cur:
                        H={c for c in range(C) if gg[r+1][c]==0}
                        new=set()
                        for e in cur:
                            c=e
                            while c>=0 and c not in H: c-=1
                            if c<0: c=0
                            new.update(range(c,e+1))
                            c=e
                            while c<C and c not in H: c+=1
                            if c>=C: c=C-1
                            new.update(range(e,c+1))
                        cur=new
                    for c in cur: out[r][c]=2
    if horiz:
        out=[row[:] for row in g]; run(g,out); return out
    gt=[list(col) for col in zip(*g)]
    out=[row[:] for row in gt]; run(gt,out)
    return [list(col) for col in zip(*out)]

